let events=[],history=[{role:'Ino',text:'I’m here. Ask me to review code, find something, or make sense of your day.'}],run=null,timer=null,activeEdge=null,inspected=null,lastFocus=null,scale=1,pan={x:0,y:0},panStart=null,filter='',eventCounter=0;
document.title=`${cfg.name} · DigitalBrain design study`;
