<header class="app-header"><div class="brand"><span class="brand-mark">${icon('spark')}</span><div>digitalbrain<div class="brand-sub">with Ino</div></div></div><div class="header-actions"><span class="prototype-badge">Interactive concept</span><span class="live-status"><i class="dot"></i><span id="header-state">Ready</span></span><button class="icon-button" data-action="search" title="Find a neuron (Ctrl+K)" aria-label="Find a neuron">${icon('search')}</button><button class="icon-button" data-action="activity" title="Activity" aria-label="View activity">${icon('activity')}</button><span class="avatar" title="Personal workspace">VH</span></div></header>
