<div class="graph-viewport" id="viewport" aria-label="Interactive brain graph. Click neurons and connections. Drag to pan; scroll to zoom."><div class="graph-world" id="world"><div class="module sources"><span class="module-label">Sources <em>2 neurons</em></span></div><div class="module mind"><span class="module-label">Intelligence <em>3</em></span></div><div class="module sales"><span class="module-label">Customer context <em>1</em></span></div><div class="module dev"><span class="module-label">Engineering <em>2</em></span></div><svg class="connections" id="edges" viewBox="0 0 1060 550" aria-label="Synapses"></svg><div id="nodes"></div></div></div>
